/// <summary>
/// This is the controller class for the tier rate calculation.
/// </summary>
public class METTierRateCalculationController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Creates the new memory for the class.
/// </summary>
protected void new()
{
    super(classStr(METTierRateCalculationService), methodStr(METTierRateCalculationService, process), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// To construct METTierRateCalculationController class.
/// </summary>
public static METTierRateCalculationController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    METTierRateCalculationController controller;
    controller = new METTierRateCalculationController();
    controller.parmExecutionMode(_executionMode);

    return controller;
}

/// <summary>
/// Main method of METTierRateCalculationController class
/// </summary>
public static void main(Args _args)
{
    METTierRateCalculationController controller = new METTierRateCalculationController();
    FormRun caller = _args.caller();

    //This method will help to get only the marked records from the Grid
    MultiSelectionHelper helper  = MultiSelectionHelper::createFromCaller(caller);

    TAMRebateDeal rebateDeal = helper.getFirst();
    controller.parmArgs(_args);
    METTierRateCalculationContract contract = controller.getDataContractObject();
    contract.parmFromDate();
    contract.parmToDate();
    contract.parmRebateDealRecId(rebateDeal.Deal);

    controller.startOperation();
}

/// <summary>
/// To set caption of a batch job
/// </summary>
public ClassDescription defaultCaption()
{
    return "@MET:TierRateCalculation";
}

/// <summary>
/// Determines if job can go batch
/// </summary>
/// <returns>Always true</returns>
public boolean canGoBatch()
{
    return true;
}
